import { cacheLife, cacheTag } from 'next/cache'
import { getPosts } from '@/lib/api'

'use cache'

export default async function Home() {
  cacheLife({ revalidate: 3600 })
  cacheTag('posts')

  const posts = await getPosts()

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <strong>{post.title}</strong>
            <span> — {post.author}</span>
          </li>
        ))}
      </ul>
    </main>
  )
}

